parameters.jsCode:
// Aca se decide si la conversacion necesita una vuelta de preguntas antes de buscar en el
// corpus. Es una decision de flujo, no de redaccion: el Parser Agent dice que le falta,
// pero quien corta el paso a la busqueda es este nodo, con reglas verificables.
//
// El texto que lee el usuario se arma aca y no en el agente. El modelo solo aporta las
// preguntas; el encabezado, el orden y la salida honrosa ("puedo orientarte igual") son
// fijos. Asi el mensaje de preguntas siempre se reconoce despues por su encabezado, que es
// justamente lo que impide preguntar dos veces seguidas.
const CLARIFICATION_HEADING = 'Para orientarte mejor';
// El XAI Agent tambien puede cerrar su respuesta con preguntas, bajo su propio encabezado.
// Cuentan igual: si el ultimo turno del asistente ya pregunto, este no vuelve a preguntar.
const XAI_FOLLOW_UP_HEADING = 'Para afinar la orientacion';
const MAX_QUESTIONS = 3;

const output = $json.output || {};
// El nodo Agent no propaga el item de entrada, asi que el historial se lee del Webhook.
const body = $('Webhook').first().json.body || {};
const previousMessages = Array.isArray(body.previous_messages) ? body.previous_messages : [];

const questions = (Array.isArray(output.clarifying_questions) ? output.clarifying_questions : [])
  .map((question) => String(question || '').trim())
  .filter(Boolean)
  .slice(0, MAX_QUESTIONS);

const ALLOWED_SUFFICIENCY = ['SUFFICIENT', 'PARTIAL', 'INSUFFICIENT'];
const declared = String(output.information_sufficiency || '').trim().toUpperCase();
// Sin senal utilizable el flujo queda como estaba: se busca y se responde.
const sufficiency = ALLOWED_SUFFICIENCY.includes(declared) ? declared : 'SUFFICIENT';

// Solo importa el ultimo turno del asistente. Si ese turno ya fue una tanda de preguntas,
// el mensaje actual es la respuesta del usuario y toca orientar, aunque siga faltando algo:
// preguntar de nuevo sobre la respuesta recien dada es el bucle que hay que evitar. Turnos
// mas antiguos no bloquean, porque un tema nuevo mas adelante puede merecer sus preguntas.
const lastAssistantMessage = [...previousMessages]
  .reverse()
  .find((message) => String(message.role || '').trim().toUpperCase() === 'ASSISTANT');
const lastAssistantContent = String((lastAssistantMessage || {}).content || '');
const askedInPreviousTurn = lastAssistantContent.includes(CLARIFICATION_HEADING)
  || lastAssistantContent.includes(XAI_FOLLOW_UP_HEADING);

const shouldAsk = sufficiency === 'INSUFFICIENT' && questions.length > 0 && !askedInPreviousTurn;

// Cuando se pregunta, el turno se agota aca: no hay busqueda ni cita que mostrar, y por eso
// cuesta un token en vez de tres. La salida tiene que dejar seguir al usuario que no sabe o
// no quiere responder, o las preguntas se vuelven un requisito para ser atendido.
const message = [
  `**${CLARIFICATION_HEADING}**`,
  '',
  'Puedo ayudarte con esto, pero un par de datos generales cambian bastante la orientacion:',
  '',
  ...questions.map((question) => `- ${question}`),
  '',
  'Responde solo lo que sepas y sin datos personales sensibles. Si prefieres, dime "sigue igual" y te doy una orientacion general con lo que ya me contaste.',
].join('\n');

return [{
  json: {
    ...$json,
    clarification: {
      status: sufficiency,
      questions,
      shouldAsk,
      askedInPreviousTurn,
      // Las preguntas que no cortan el flujo siguen viajando: el RAG y el XAI las usan para
      // no dar por cierto lo que el usuario nunca dijo.
      message: shouldAsk ? message : '',
    },
  },
}];

// El idioma decide unicamente en que lengua se lee la orientacion. El razonamiento
// juridico, el corpus y las citas siguen siendo en espanol de punta a punta.
const SUPPORTED = ['es', 'qu', 'ay'];
const body = $json.body || {};
const requested = String(body.language || '').trim().toLowerCase();
// Un idioma ausente o desconocido cae a espanol en lugar de fallar: el backend ya valida
// la lista blanca, y aca un valor raro no debe costarle el turno al usuario.
const language = SUPPORTED.includes(requested) ? requested : 'es';
return [{ json: { ...$json, body: { ...body, language } } }];

