parameters.jsCode:
// Punto en el que la entrada queda normalizada al espanol, venga en la lengua que venga, y
// en el que se decide el idioma EFECTIVO del turno. A partir de aca todo el pipeline
// (Parser, RAG, XAI) trabaja como siempre lo hizo, sin enterarse de que existen otros
// idiomas.
//
// El idioma que manda el frontend es la preferencia de interfaz, no una lectura del texto.
// Por eso TODOS los turnos pasan por Translate Inbound, que ademas de traducir declara en
// `detectedLanguage` la lengua que realmente leyo, y es esa lectura la que gobierna el turno.
//
// El caso que obliga a no saltarse ninguno es el mas importante del producto: la app arranca
// en espanol, y un hablante de quechua o aymara que no encuentra el selector de idioma
// escribe igual en su lengua. Si la deteccion solo corriera cuando ya se pidio quechua o
// aymara, esa persona -la razon de ser de la funcion- no la veria nunca.
//
// El declarado se conserva en `language_requested` para que el frontend pueda explicar el
// cambio y ofrecer cambiar la app; cuando coinciden, no hay nada que explicar.
const SUPPORTED = ['es', 'qu', 'ay'];
const base = $('Resolve Language').first().json;
const body = base.body || {};
const requested = body.language || 'es';
const parsed = $json.output || {};
// Un detector confundido, o un fallo del nodo (que pasa de largo por onError), no debe
// costarle el turno a nadie: sin lectura utilizable se respeta lo que pidio la interfaz.
const detected = SUPPORTED.includes(parsed.detectedLanguage) ? parsed.detectedLanguage : null;
const language = detected || requested;
// Si el texto ya estaba en espanol no hay nada que traducir, aunque la interfaz pidiera otra
// lengua: el original ES el espanol canonico.
const translated = language === 'es'
  ? ''
  : String(parsed.translation ?? $json.text ?? '').trim();
// Si la traduccion fallo o vino vacia, se sigue con el texto original. La orientacion
// saldra peor, pero el usuario no pierde el turno ni sus tokens por un fallo del traductor.
const message = translated || body.message;
return [{
  json: {
    ...base,
    body: {
      ...body,
      message,
      // Lo que el usuario escribio de verdad. Se conserva para poder mostrarlo tal cual.
      message_original: body.message,
      language,
      language_requested: requested,
    },
  },
}];

// Las tres ramas terminales arman el mismo objeto `payload`, con el contrato exacto que
// espera el backend. Antes cada una lo construia por su cuenta dentro del nodo de
// respuesta, con formas ligeramente distintas; ahora convergen para poder traducirse en un
// solo lugar.
const output = $json.output || {};
// El idioma efectivo lo fija Normalized Input leyendo el texto, no la preferencia de
// interfaz que llego en el request: se responde en la lengua en que se escribio.
const normalized = $('Normalized Input').first().json.body || {};
const language = normalized.language || 'es';
const languageRequested = normalized.language_requested || language;
return [{
  json: {
    language,
    languageRequested,
    payload: {
      message: output.message || 'Puedo orientar sobre Derecho de Familia en Peru. Cuentame de forma general tu situacion familiar y que necesitas decidir, sin incluir datos personales.',
      citations: [],
      confidenceStatus: null,
      confidenceReason: null,
      nextSteps: [],
      specialistSupportRecommended: false,
      citationSupportStatus: null,
      clarifyingQuestions: [],
      agentTokenCost: 1,
    },
  },
}];

const clarification = $json.clarification || {};
// El idioma efectivo lo fija Normalized Input leyendo el texto, no la preferencia de
// interfaz que llego en el request: se responde en la lengua en que se escribio.
const normalized = $('Normalized Input').first().json.body || {};
const language = normalized.language || 'es';
const languageRequested = normalized.language_requested || language;
return [{
  json: {
    language,
    languageRequested,
    payload: {
      message: clarification.message,
      citations: [],
      confidenceStatus: null,
      confidenceReason: null,
      nextSteps: [],
      specialistSupportRecommended: false,
      citationSupportStatus: null,
      clarifyingQuestions: clarification.questions || [],
      // Preguntar cuesta un token; recuperar y redactar cuesta tres.
      agentTokenCost: 1,
    },
  },
}];

const output = $json.output || {};
// Brazo de ablacion sin capa de explicabilidad: la respuesta viaja sin citas, sin
// localizador, sin confianza y sin pasos. Los campos se envian vacios y no ausentes para
// que el contrato con el backend siga siendo el mismo y la comparacion mida la
// explicabilidad y no un fallo de transporte.
const normalized = $('Normalized Input').first().json.body || {};
const language = normalized.language || 'es';
const languageRequested = normalized.language_requested || language;
return [{
  json: {
    language,
    languageRequested,
    payload: {
      message: output.answer || $json.answer || 'Con lo que cuentas hasta ahora, puedo darte una orientacion general de Derecho de Familia.',
      citations: [],
      confidenceStatus: null,
      confidenceReason: null,
      nextSteps: [],
      specialistSupportRecommended: false,
      citationSupportStatus: 'NONE',
      clarifyingQuestions: [],
      agentTokenCost: 3,
    },
  },
}];

